Add({
	kind = "topic",
	id = "sentinels",
	title = "Sentinels",
	category = "group",
	region = "darnassus",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Sentinels are the warriors of the {link:night-elves}night elves{/link}. For thousands of years they have guarded the forests of {link:kalimdor}Kalimdor{/link}, and they answer to the High Priestess of Elune. Most are women, huntresses who wield the gifts of the goddess as well as the glaive and the bow.]=],
		},
		{
			title = "Origins",
			text = [=[After the {link:great-sundering}Great Sundering{/link}, while the druids slept in the {link:emerald-dream}Emerald Dream{/link}, the priestesses of Elune and their warriors kept watch over the {link:night-elves}kaldorei{/link}. Through those long ages the Sentinels became the shield of their people.]=],
		},
		{
			title = "In the Present Day",
			text = [=[Sentinels keep watch in every village of {link:teldrassil}Teldrassil{/link} and on every road. They guard the Oracle Tree, carry its messages to {link:darnassus}Darnassus{/link}, and fight the {link:gnarlpine-furbolgs}Gnarlpine{/link} and the harpies. Beyond the tree they hold posts in {link:darkshore}Darkshore{/link}, {link:ashenvale}Ashenvale{/link} and {link:feralas}Feralas{/link}. {link:shandris-feathermoon}General Feathermoon{/link} sees that each of them has time to pray, and in Darnassus they watch the city itself, for they fear that something is amiss.]=],
		},
	},
})
